import java.util.ArrayList;
import java.util.List;
import java.util.Scanner;

public class Main {
    static List<Long> sequence = new ArrayList<>();

    static long compute(long n, long l) {
        long quotient = n / sequence.get((int) l);
        n %= sequence.get((int) l);
        if (n == 0) {
            return quotient * l;
        }
        long val1 = l + compute(sequence.get((int) l) - n, l - 1);
        long val2 = compute(n, l - 1);
        return quotient * l + Math.min(val1, val2);
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        sequence.clear();
        long m = 0;
        while (sequence.size() < 17) {
            sequence.add(m);
            m = m * 10 + 1;
        }
        long n = sc.nextLong();
        System.out.println(compute(n, 16));
        sc.close();
    }
}
